/** Shared types for the files generated by extract_counties.py. */

/** WGS84 coordinates in GeoJSON order, in decimal degrees. */
export type Position = [longitude: number, latitude: number];

/** A closed boundary ring; the first and last positions are equal. */
export type LinearRing = Position[];

export interface CountyPolygonGeometry {
	type: 'Polygon';
	/** Exterior ring first, followed by any holes. */
	coordinates: LinearRing[];
}

export interface CountyMultiPolygonGeometry {
	type: 'MultiPolygon';
	/** Each polygon contains its exterior ring followed by any holes. */
	coordinates: LinearRing[][];
}

export type CountyGeometry = CountyPolygonGeometry | CountyMultiPolygonGeometry;

/** GeoJSON properties, or a CSV row after parsing its center coordinates. */
export interface CountyProperties {
	/** Five-character county FIPS code, including leading zeros. */
	geoid: string;
	/** Census name, including county equivalents such as parishes and boroughs. */
	name: string;
	/** Two-character state or territory FIPS code, including leading zeros. */
	state_fips: string;
	/** State or territory postal abbreviation. */
	state_abbr: string;
	state_name: string;
	/** Area-weighted geographic centroid latitude in WGS84 decimal degrees. */
	center_lat: number;
	/** Area-weighted geographic centroid longitude in WGS84 decimal degrees. */
	center_lon: number;
}

/** One county or county equivalent in output/counties.geojson. */
export interface CountyFeature {
	type: 'Feature';
	/** Matches properties.geoid. */
	id: string;
	properties: CountyProperties;
	geometry: CountyGeometry;
}

/** The complete output/counties.geojson document, sorted by GEOID. */
export interface CountyFeatureCollection {
	type: 'FeatureCollection';
	features: CountyFeature[];
}

/** A row from output/counties.csv before converting center coordinates to numbers. */
export type CountyCsvRow = { [Field in keyof CountyProperties]: string };
